Object.assign(window.LEVELS, {

  'm1-1': { segs: [
    { t: 'text', h: '先认识三样东西', b:
      '<p>你按一下开机键，屏幕黑着，过几秒跳出一个标志，再过几秒进了桌面。这十几秒里电脑做了几百件事，你现在不需要知道全部，只要认识三样东西，就能解释平时遇到的大部分问题。</p>' +
      '<p>这三样东西是：<strong>CPU、内存、硬盘</strong>。买电脑时商家念的那堆参数，i5、16G、512G，说的就是它们。</p>' },
    { t: 'quiz', q: '关机之后，你的照片和文档还在。它们存在哪儿？',
      opts: ['内存里', '硬盘里', 'CPU 里', '显卡里'], a: 1,
      why: '硬盘是断电也不会忘的存储。内存一断电就忘，CPU 只负责算，不负责存。' },
    { t: 'text', h: '内存：东西正在这儿用', b:
      '<p>内存是硬盘和 CPU 之间的中转站。你打开一个软件，电脑先把它的内容从硬盘搬到内存里，然后 CPU 从内存里读。内存比硬盘快几十倍，CPU 才不用干等着。</p>' +
      '<p>内存的特点是：<strong>快，但小，而且一断电就忘。</strong></p>' +
      '<p>你写 Word 写了半小时没保存，突然停电，那半小时就没了 —— 因为那半小时的内容一直在内存里，还没写回硬盘。这就是为什么软件都会提醒你保存：<strong>保存这个动作，就是把内存里的东西写进硬盘。</strong></p>' },
    { t: 'quiz', q: '「硬盘管记住，内存管正在用」。下面哪种情况丢的是内存里的东西？',
      opts: ['电脑断电后，昨天存的照片不见了', '写了半小时没保存，停电后半小时的内容没了', '把文件拖进回收站清空了', '硬盘满了，新文件存不进去'], a: 1,
      why: '没保存的内容一直在内存里，内存断电就忘。A 和 C 动的是硬盘上的东西，D 是硬盘容量问题。' },
    { t: 'text', h: 'CPU：干活的', b:
      '<p>CPU 是电脑里真正在算东西的部件。点一下鼠标、敲一个键、播放一段视频，背后都是 CPU 在执行一串指令，它每秒能执行几十亿次，是整台电脑里最快的部件。</p>' +
      '<p>两个关键指标：<strong>核心数</strong>（能同时干几件事，四核就是四个工人）和 <strong>频率</strong>（每个工人干活的速度）。现在看到的 i5、i7、R7 是型号档次，同一代里数字大的通常核多、频率高。</p>' +
      '<h3>一个真实的场景</h3>' +
      '<p>你写文档、开浏览器查资料、挂微信。一开始很流畅，半小时后开了十几个标签页，切窗口开始卡。打开任务管理器一看，内存用了 90%。</p>' +
      '<p><strong>原因很清楚：内存不够了。</strong>系统只好把一部分内容先挪回硬盘，等要用时再搬回来，硬盘比内存慢几十倍，所以卡。关掉几个标签页，内存立刻降下来。</p>' +
      '<p>最值得记住的是：<strong>卡的原因通常是内存不够，跟 CPU 关系不大</strong>，CPU 大部分时间其实很闲。</p>' },
    { t: 'quiz', q: '任务管理器显示内存 92%、CPU 20%，但电脑很卡。最可能的原因是？',
      opts: ['CPU 不够快，该换 CPU 了', '内存不够，系统在拿硬盘临时顶替', '硬盘容量满了', '显卡坏了'], a: 1,
      why: '内存装不下时，系统会把一部分内容挪回硬盘周转，硬盘比内存慢几十倍，所以卡。CPU 只用了 20%，说明它很闲。' },
    { t: 'final', qs: [
      { q: '「保存」这个动作，本质上把数据从哪里写到了哪里？', opts: ['CPU → 内存', '内存 → 硬盘', '硬盘 → 内存', '内存 → CPU'], a: 1, why: '保存就是把内存里正在用的东西，写进断电也不会忘的硬盘。' },
      { q: '预算有限，换哪一样最能明显改善「开机慢、打开软件慢」？', opts: ['换更高型号的 CPU', '把机械硬盘换成固态硬盘', '加一根内存条', '换更大的显示器'], a: 1, why: '固态和机械的读写速度差十倍以上，这个差别比 CPU 型号的差别明显得多。' },
      { q: '关于「CPU / 内存 / 硬盘」这个三件套模型，哪句话是对的？', opts: ['它能解释电脑的一切问题', '它是简化模型，显卡、散热、系统调度也在起作用', '内存越大就一定不卡', 'CPU 是电脑里唯一决定快慢的部件'], a: 1, why: '它是个够用的简化模型，但真实情况复杂得多；软件写得烂或跑吃 CPU 的任务时，加内存也没用。' }
    ]}
  ]},

  'm1-2': { segs: [
    { t: 'text', h: '电脑里只有两个数字', b:
      '<p>你在电脑上看到的一切，文字、照片、音乐、视频，在电脑内部都只是两个数字：0 和 1。这是字面意思，没有别的隐藏状态。</p>' +
      '<p>那怎么表示更多的意思？靠数量。一个位置只能表示两种意思，两个位置四种，三个位置八种。八个位置放在一起能表示 256 种，刚好够表示英文字母、数字、标点 —— 这八个位置合起来就叫<strong>一个字节</strong>。</p>' +
      '<p>你听到的「这个文件 3 MB」，说的就是它占了大约三百万个这样的八位组合。</p>' },
    { t: 'quiz', q: '一个字节（8 个二进制位）一共能表示多少种不同的值？',
      opts: ['8 种', '16 种', '256 种', '1024 种'], a: 2,
      why: '每个位有 2 种可能，8 个位就是 2 的 8 次方 = 256，取值范围是 0～255。' },
    { t: 'text', h: '文字怎么变成数字', b:
      '<p>既然电脑里只有数字，文字就得先翻译成数字。翻译靠一张表：约定「65 代表大写 A，97 代表小写 a」，存一个字母其实是存它的编号。这套约定就是<strong>编码</strong>。</p>' +
      '<p>问题在于约定不止一套。最早的 ASCII 只定了 128 个字符，管英文够了；后来各国各自加自己的表，中文常用的有 GBK 和 UTF-8 两套。</p>' +
      '<p><strong>同一个汉字，在 GBK 里是一串数字，在 UTF-8 里是另一串。</strong>这就是乱码的来源。</p>' },
    { t: 'quiz', q: '一个文件用错误的编码打开，通常会怎样？',
      opts: ['文件被损坏，内容永久丢失', '显示成乱码，换个正确编码打开就正常', '文件大小会变小', '电脑会提示硬盘有坏道'], a: 1,
      why: '字节没变，只是查错了对照表。用正确的编码重新打开就恢复，文件本身没坏。' },
    { t: 'text', h: '一个到现在还在发生的坑', b:
      '<p>一个学生从学校系统导出学生名单，拿到一个 <code>.csv</code> 文件，用 Excel 打开，中文全是乱码。他以为是文件坏了，重新导出了三次，都一样。</p>' +
      '<p>后来学长告诉他：别直接双击，先打开 Excel，用「数据」里的「从文本导入」，过程中手动选编码，选 UTF-8。中文正常了。</p>' +
      '<p><strong>问题不在文件上，在打开方式上。</strong>系统导出的是 UTF-8，Excel 双击打开时按系统默认编码读，中文 Windows 默认是 GBK，两边对不上。</p>' +
      '<p>这个坑从有中文电脑那天起就存在。你以后遇到中文乱码，第一反应应该是「编码不对」，而不是「文件坏了」。</p>' },
    { t: 'final', qs: [
      { q: '一个汉字在 UTF-8 里通常占几个字节？', opts: ['1 个', '2 个', '3 个', '8 个'], a: 2, why: 'UTF-8 是变长编码，常用汉字一般占 3 个字节，英文字母仍是 1 个。所以同样字数的中文文档比英文大好几倍。' },
      { q: '关于改编码，下面哪句是对的？', opts: ['改编码会改变文件里的文字内容', '改编码只改变硬盘上存的那串数字，文字不变', 'UTF-8 是唯一正确的编码', '所有乱码都是文件损坏导致的'], a: 1, why: '转对了文字正常，转错了文字就毁了 —— 所以转之前一定先复制一份。' },
      { q: '看到「涓€」这种字，最可能的原因是？', opts: ['文件被病毒感染', '把 UTF-8 编码的文件当成 GBK 读了', '把 GBK 编码的文件当成 UTF-8 读了', '字体没装'], a: 2, why: '反过来：看到「æ–‡ä»¶」这种奇怪字母组合，才是把 UTF-8 当成别的编码读了。' }
    ]}
  ]},

  'm1-3': { segs: [
    { t: 'text', h: '电脑里的东西都长在一棵树上', b:
      '<p>你打开「此电脑」或「访达」，看到桌面、文档、下载、图片几个大类，点进「文档」是你自己建的文件夹，再点进去是文件。一层一层往下，这就是<strong>树</strong>。</p>' +
      '<p>树的根就是最上面那一层：Windows 上叫「此电脑」，Mac 上叫「Macintosh HD」，Linux 和服务器上就是一个斜杠 <code>/</code>。</p>' +
      '<p>从根往下走，把经过的每一层名字用斜杠隔开写下来，就是这个文件的<strong>路径</strong>，比如 <code>/Users/zhangsan/Desktop/报告.pdf</code>。</p>' },
    { t: 'quiz', q: '路径 <code>/Users/zhangsan/Desktop/报告.pdf</code> 里，最前面那个 <code>/</code> 是什么？',
      opts: ['一个分隔符，没有含义', '根目录，整棵树的起点', '用户名', '盘符'], a: 1,
      why: '最前面的斜杠就是根，整棵树从它开始往下长。后面那些斜杠才是分隔符。' },
    { t: 'text', h: '为什么有的文件你打不开', b:
      '<p>同一台电脑上文件是有主的。每个文件都记着三件事：<strong>它是谁的、谁能看它、谁能改它</strong>。规矩是把人分成三类（主人 / 同组 / 其他人），每类分别设三种许可（读 / 写 / 执行），合起来九种组合。</p>' +
      '<p>最常见让人抓狂的情况是：<strong>文件明明是你的，你也看得见，但就是打不开、改不了、删不掉。</strong></p>' +
      '<p>原因通常不在这个文件本身，而在它<strong>上面那一层</strong>。在 Mac 和 Linux 上，文件夹除了「能不能看里面有什么」，还有一个单独的「能不能进去」。你能看见里面有啥，但没有「进去」的许可，那里面所有东西你都碰不到，哪怕每个文件的许可都开着。</p>' },
    { t: 'quiz', q: '文件是你的、看得见，却打不开也删不掉。最常见的原因是？',
      opts: ['文件被病毒感染了', '硬盘有坏道', '它所在的那个文件夹没给你「进去」的许可', '文件名里有特殊字符'], a: 2,
      why: '文件的许可没问题，是它所在的文件夹你没被允许进去。其次常见的是想改系统文件但不是管理员。' },
    { t: 'text', h: '为什么「改成所有人可读写」是个坏建议', b:
      '<p>遇到打不开，网上最常见的建议是「把权限改成所有人可读写」。它确实能解决，但同时也把这道门整个拆掉了：这台电脑上任何人都能改这个文件。</p>' +
      '<p>更好的做法是先搞清楚是谁没有许可，然后只给那一个身份加上。<strong>还有一条更要小心：不要对系统目录用「递归」改权限</strong> —— 看到 <code>-R</code> 这个参数要格外警惕，在系统目录上用可能让电脑起不来。</p>' +
      '<h3>树之外还有什么</h3>' +
      '<p>树有个绕不开的代价：一个东西只能待在一个位置。想让它同时属于「课程」和「项目」，折中办法叫<strong>链接</strong> —— 它几乎不占地方，里面只写着真正的东西在哪。这个想法后面到处都会出现：数据库的外键、编程里的引用、网页上的超链接，都是同一件事。</p>' +
      '<p>云盘和图片服务大多不用文件夹，数据库里你看不到文件，标签系统解决了「一个东西只能在一个地方」的老问题。它们不是来取代文件系统的，只是管的事不同。</p>' },
    { t: 'final', qs: [
      { q: '遇到权限问题，更好的第一反应是什么？', opts: ['立刻改成所有人可读写', '用管理员身份重试', '先问「是谁没有许可」，只给那一个身份加', '删掉重建'], a: 2, why: '给所有人开门能解决但留隐患。先定位是哪个身份缺许可，范围最小的改法最安全。' },
      { q: '<code>mkdir -p 练习/课程/笔记</code> 这条命令在做什么？', opts: ['只建一个叫「练习」的文件夹', '把路径上缺的文件夹都建出来，一次建三层', '把「笔记」改名叫「练习」', '删除这条路径'], a: 1, why: '-p 的意思是「路径上缺的都补上」，一条命令就能建出多层。' },
      { q: '<code>ls -l</code> 输出里 <code>-rw-r--r--</code> 开头是 <code>d</code> 时表示什么？', opts: ['这是个隐藏文件', '这是个文件夹', '这是个可执行程序', '这个文件已损坏'], a: 1, why: '开头是 d 代表 directory（文件夹），是 - 代表普通文件。后面九个字符分三组，对应主人 / 同组 / 其他人的读(w)、写(r)、执行(x)。' }
    ]}
  ]},

  'm1-4': { segs: [
    { t: 'text', h: '格式是人为约定的', b:
      '<p>你电脑里的每个文件，说到底都只是一串数字。同样的这串数字，用不同的方式去读，会读出完全不同的东西。</p>' +
      '<p>假设文件里存着 <code>4E 2D 65 87</code> 这几个字节：约定「按 UTF-8 读是两个汉字」，你看到「中文」；约定「按 GBK 读」，你看到另外两个字；约定「按图片读是一小块像素的颜色」，你看到两个橙色像素。<strong>同一串数字，三种读法，三种结果。</strong></p>' +
      '<p>这个约定就是<strong>格式</strong>。后缀名（<code>.txt</code>、<code>.jpg</code>）只是给系统看的提示，告诉它该用哪个程序打开，不代表文件里真的是什么。</p>' },
    { t: 'quiz', q: '把一张图片改名成 <code>.txt</code>，会发生什么？',
      opts: ['它真的变成文本文件了', '它还是图片，只是双击打不开了', '文件会被系统自动转换', '文件会损坏'], a: 1,
      why: '扩展名骗不了内容。系统按后缀找程序，程序按真实内容去读，两边对不上就报错。' },
    { t: 'text', h: '常见格式各自解决什么', b:
      '<ul>' +
      '<li><strong><code>.txt</code></strong> 纯文本，只有文字没样式。不会坏，二十年后还能打开，但不能排版。</li>' +
      '<li><strong><code>.md</code></strong> 也是纯文本，但能用 <code>#</code> 表示标题、<code>**</code> 表示加粗。写技术文档大多用它。</li>' +
      '<li><strong><code>.json</code></strong> 给程序看的结构化数据，花括号和方括号把数据组织起来，你在网页上填的表单提交时多半就长这样。</li>' +
      '<li><strong><code>.csv</code></strong> 纯文本表格，一行一条记录、字段用逗号隔开。<strong>最容易出中文乱码的一种。</strong></li>' +
      '<li><strong><code>.docx</code> / <code>.pdf</code></strong> 带样式。<code>.docx</code> 其实是个压缩包；<code>.pdf</code> 保证在哪打开都长一样，代价是文字不好拿出来用。</li>' +
      '<li><strong><code>.jpg</code> / <code>.png</code></strong>：<code>.jpg</code> 丢细节换体积，适合照片；<code>.png</code> 不丢细节、支持透明，适合截图和图标。</li>' +
      '</ul>' },
    { t: 'quiz', q: '要存一张需要透明背景的图标，选哪个格式？',
      opts: ['.jpg', '.png', '.pdf', '.csv'], a: 1,
      why: 'PNG 不丢细节、支持透明通道。JPG 不支持透明，而且放大会看到模糊的方块。' },
    { t: 'text', h: '它的边界', b:
      '<p><strong>纯文本最保险，但表达力最弱。</strong>希望十年后还能打开就用 <code>.txt</code> 或 <code>.md</code>；需要排版、图片、公式就得用 <code>.docx</code> 或 <code>.pdf</code>，代价是可能要靠特定软件才能开。</p>' +
      '<p><strong>格式转换会丢东西。</strong><code>.docx</code> 转 <code>.pdf</code> 排版会变，<code>.png</code> 转 <code>.jpg</code> 画质会降。转来转去，信息只会少不会多。<strong>一条原则：改格式之前先复制一份。</strong></p>' +
      '<p>下次遇到打不开或乱码，要说清三件事再问：文件从哪来的、你想用它做什么、屏幕上具体是什么现象。只说「我的文件打不开」，谁也只能猜。</p>' },
    { t: 'final', qs: [
      { q: 'CSV 文件用 Excel 双击打开中文乱码，最可能的原因是？', opts: ['文件下载时损坏了', 'Excel 按系统默认编码（GBK）去读 UTF-8 的文件', '文件里混入了图片', 'Excel 版本太旧'], a: 1, why: '正确做法是用「数据 → 从文本导入」，过程中手动选 UTF-8。' },
      { q: '关于格式转换，哪句是对的？', opts: ['转换只是换个读法，信息不会丢', '转来转去信息只会少不会多', 'PDF 转 Word 一定保持排版', '所有格式都能无损互转'], a: 1, why: '排版、画质都可能在转换中损失，所以转换前一定先备份原件。' },
      { q: 'JSON 这种格式主要是给谁看的？', opts: ['给人阅读的文档', '给程序读的结构化数据', '用来存照片的', '用来压缩文件的'], a: 1, why: '它用花括号和方括号组织数据，程序一眼就能分清哪部分是名字、哪部分是列表。' }
    ]}
  ]},

  'm1-5': { segs: [
    { t: 'text', h: '它不是另一个系统', b:
      '<p>终端（黑窗口）不是藏在电脑里的另一套东西。它和桌面、文件夹窗口一样，都是<strong>操作同一台电脑的一种方式</strong>，只不过你用打字代替了鼠标点击。</p>' +
      '<p>为什么程序员爱用它？很多事用鼠标要点十几下，敲一行命令就完了；而且命令可以写进脚本，让电脑自己重复执行。</p>' },
    { t: 'quiz', q: '关于终端和图形界面，下面哪句话是对的？',
      opts: ['终端是电脑里另一套独立的系统', '它们操作的是同一台电脑，只是交互方式不同', '终端比图形界面权限更高，能做任何事', '只有 Linux 才有终端'], a: 1,
      why: '终端只是用打字代替点击，背后的文件和程序完全一样。Windows、macOS、Linux 都有。' },
    { t: 'text', h: '先记住三个命令', b:
      '<p>打开终端，你会看到一个光标在闪，前面通常有一串路径，表示你「现在在哪个文件夹里」。</p>' +
      '<ul>' +
      '<li><code>pwd</code> —— 打印当前所在的路径（我在哪儿）</li>' +
      '<li><code>ls</code> —— 列出当前文件夹里有什么（这儿有什么）</li>' +
      '<li><code>cd 目录名</code> —— 进入某个文件夹（去那儿）</li>' +
      '</ul>' +
      '<p>两个特殊写法：<code>cd ..</code> 回到上一级，<code>cd ~</code> 直接回自己的家目录。Windows 用户需要装 Git Bash 才能用这一套命令，系统自带的那两个命令行用不了。</p>' },
    { t: 'quiz', q: '<code>cd ..</code> 这条命令在做什么？',
      opts: ['进入下一级子文件夹', '回到上一级文件夹', '列出当前文件夹的所有内容', '删除当前文件夹'], a: 1,
      why: '两个点 <code>..</code> 代表上一级目录，一个点 <code>.</code> 代表当前目录。' },
    { t: 'text', h: '卡住了怎么办', b:
      '<p>终端里最容易慌的时刻是「命令跑起来没反应」。先分辨两件事：</p>' +
      '<ul>' +
      '<li>它在<strong>等你输完</strong>：比如引号没闭合，光标还在等你。</li>' +
      '<li>它在<strong>真的干活</strong>：比如装依赖、拷贝大文件。这时别乱按，等它跑完。</li>' +
      '</ul>' +
      '<p><strong><code>Ctrl + C</code> 是终端里的「撤销键」</strong>，任何卡住的情况先按它中断当前命令，不会弄坏电脑。Windows 上如果提示「不是内部或外部命令」，说明你打开的是系统命令提示符而不是 Git Bash。</p>' },
    { t: 'final', qs: [
      { q: '想看「我现在在哪个文件夹」，用哪条命令？', opts: ['ls', 'pwd', 'cd', 'cat'], a: 1, why: 'pwd = print working directory，打印当前工作目录。' },
      { q: '想看「这个文件夹里有什么」，用哪条命令？', opts: ['pwd', 'ls', 'cd ..', 'rm'], a: 1, why: 'ls = list，列出目录内容。' },
      { q: '<code>cd ~</code> 会去哪里？', opts: ['根目录', '自己的家目录', '上一级目录', '桌面'], a: 1, why: '<code>~</code> 是家目录的简写，Windows 上通常对应 C:\\Users\\你的名字。' }
    ]}
  ]},

  'm1-6': { segs: [
    { t: 'text', h: '终端是窗口，Shell 是里面的程序', b:
      '<p>这两个词经常被混着用，但它们是两样东西：<strong>终端是那个窗口</strong>，负责显示文字、接收你的按键；<strong>Shell 是窗口里跑的那个程序</strong>，负责把你敲的话翻译成电脑要做的事。</p>' +
      '<p>Shell 也有好几种，最常见的是 <code>bash</code> 和 <code>zsh</code>（Mac 新系统默认是 zsh）。它们能懂的命令基本一样，日常使用感觉不到差别。</p>' +
      '<p>你敲 <code>ls</code> 回车，Shell 做的事是：找到叫 <code>ls</code> 的那个程序、让它跑起来、把结果打印回窗口。</p>' },
    { t: 'quiz', q: '终端和 Shell 的关系是？',
      opts: ['它们是同一个东西的两种叫法', '终端是窗口，Shell 是窗口里跑的程序', 'Shell 是硬件，终端是软件', 'Shell 只在 Linux 上存在'], a: 1,
      why: '终端负责显示和输入，Shell 负责解释命令。换一个 Shell，窗口还是那个窗口。' },
    { t: 'text', h: '环境变量和 PATH', b:
      '<p>Shell 里有一批「全局变量」叫<strong>环境变量</strong>，所有程序都能读。其中最重要的一个叫 <code>PATH</code>。</p>' +
      '<p>你敲 <code>ls</code> 的时候，系统并不知道 <code>ls</code> 在哪。它做的是：沿着 PATH 里列的一串目录，一个一个进去找，找到就运行，一个都找不到就报「command not found」。</p>' +
      '<p>敲 <code>which ls</code> 能看到它到底躺在哪 —— 这就是「装软件」的结果：<strong>一个文件被放进了某个目录，并且那个目录被登记进了 PATH。</strong></p>' },
    { t: 'quiz', q: '装完 Python，敲 <code>python --version</code> 却提示找不到命令，最可能的原因是？',
      opts: ['Python 没装成功', '安装时没勾「Add Python to PATH」，系统不知道它在哪', '电脑内存不够', '命令拼写错了'], a: 1,
      why: '这个坑每年绊住大量新手。装开发工具时，凡是出现「Add to PATH」「环境变量」这类选项，一律勾上。' },
    { t: 'text', h: '两个让命令变好用的东西', b:
      '<p><strong>管道</strong>：用 <code>|</code> 把一个命令的输出直接喂给下一个命令当输入。<code>ls /usr/bin | wc -l</code> 就是「列出所有文件，数一下有多少行」—— 两个简单命令拼出了一个它们各自都做不到的事。</p>' +
      '<p><strong>重定向</strong>：<code>></code> 把输出写进文件（会覆盖），<code>>></code> 追加到文件末尾。注意 <code>></code> 会直接覆盖原文件，用之前确认目标文件是不是可以丢。</p>' +
      '<p>Shell 还有一份启动时会读的配置文件（<code>.bashrc</code> 或 <code>.zshrc</code>）。你写的<strong>别名</strong>和环境变量都放这里，这样每次打开终端都生效。</p>' },
    { t: 'final', qs: [
      { q: '<code>ls /usr/bin | wc -l</code> 这条命令在做什么？', opts: ['把 /usr/bin 复制一份', '统计 /usr/bin 里有多少个条目', '删除 /usr/bin', '把结果写进文件'], a: 1, why: '竖线是管道：ls 的输出交给 wc -l 去数行数。' },
      { q: '<code>echo "hi" > a.txt</code> 和 <code>> a.txt</code> 的区别是？', opts: ['没区别', '前者追加到末尾，后者覆盖整个文件', '前者覆盖整个文件，后者追加到末尾', '前者会新建文件，后者不会'], a: 2, why: '一个大于号是覆盖，两个是追加。用 > 之前先确认目标文件可以丢。' },
      { q: '想让你自定义的别名每次打开终端都生效，应该写在哪？', opts: ['随便一个 txt 文件里', '.bashrc 或 .zshrc 这类 Shell 配置文件里', '桌面上', 'PATH 里'], a: 1, why: 'Shell 启动时会读这份配置文件，写在里面的别名和环境变量才会长期生效。' }
    ]}
  ]},

  'm1-7': { segs: [
    { t: 'text', h: '两小时的活变成三秒', b:
      '<p>有个学生每周要整理一次作业：资料散在十几个文件夹里，他得手动挑出同一门课的、重命名、按周次归档，一次一个多小时。后来他写了个脚本，第一次写完加调试花了五小时，从第四周开始这件事变成双击一下、三秒。</p>' +
      '<p><strong>判断标准很朴素：这件事我要做几次。做一次的事手动做；做三次以上的，就值得写。</strong></p>' },
    { t: 'quiz', q: '脚本的本质是什么？',
      opts: ['一种需要编译的复杂程序', '一个装着命令的文本文件', '操作系统的一个功能', '一种数据库'], a: 1,
      why: '你在终端里敲的命令本来就是一行文字。把十几行写进一个文件，敲它的名字就从头到尾跑一遍 —— 这就是脚本。' },
    { t: 'text', h: '脚本能干的六类事', b:
      '<ul>' +
      '<li><strong>整理和改名</strong>：规则简单、数量巨大。</li>' +
      '<li><strong>定时任务</strong>：每天凌晨备份、每周一汇总、每月清理旧日志。这是最被低估的用途 —— 写一次，它替你工作几年。</li>' +
      '<li><strong>批量处理文本</strong>：从表格里挑出符合条件的行、把五十个文档里的某个词全替换掉。</li>' +
      '<li><strong>把多个程序串起来</strong>：下载视频 → 提取音频 → 压缩 → 上传，一条命令搞定。</li>' +
      '<li><strong>检查东西</strong>：提交前检查有没有把密码写进去。不产生直接成果，但能让你少踩坑。</li>' +
      '<li><strong>给复杂操作包一层</strong>：五条长命令写成一个脚本，团队里所有人都能用还不会敲错。</li>' +
      '</ul>' +
      '<p>脚本里其实只有两个「逻辑」：<strong>判断</strong>（如果是图片就搬到图片文件夹）和<strong>循环</strong>（对每个文件都做这件事）。学会这两个，日常脚本你就能写了。</p>' },
    { t: 'quiz', q: '下面哪种活最不值得写脚本？',
      opts: ['每周都要做一次的文件整理', '只做一次、手动十分钟就能完成的活', '每天凌晨要跑的备份', '提交代码前重复的检查流程'], a: 1,
      why: '写脚本加调试至少要一小时。判断标准就是那句：这件事你会做几次。' },
    { t: 'text', h: '选哪个语言，以及拿到脚本先看什么', b:
      '<p><strong>一句话的判断方法</strong>：跟文件和系统打交道为主，用 Bash；跟数据和网络打交道为主，用 Python。Bash 不用装任何东西、任何 Linux 服务器上都有，但处理复杂逻辑很别扭；Python 语法接近英语、第三方库极多，代价是别人要装环境才能跑。</p>' +
      '<p><strong>拿到脚本之后做三件事。</strong>第一，读一遍，找 <code>rm</code>、<code>mv</code>、<code>></code> 这三个东西 —— 有 <code>rm</code> 就问它删什么，有 <code>mv</code> 就问搬到哪、覆盖了怎么办，有 <code>></code> 就问覆盖的是哪个文件。第二，<strong>先干跑</strong>：把动手那一步换成打印，看输出跟预期一不一样。第三，<strong>先在假数据上跑</strong>。</p>' +
      '<p>让系统帮你写脚本时，要说清四件事：<strong>输入是什么、规则是什么（尤其例外情况）、输出是什么、不许做什么</strong>。最后那条最重要：「不许删除任何文件」「遇到同名就跳过」。</p>' },
    { t: 'final', qs: [
      { q: '一个脚本里出现 <code>for f in *; do ... done</code>，这是在用哪个逻辑？', opts: ['判断', '循环', '函数', '异常处理'], a: 1, why: 'for 是循环：把一堆东西里的每一个轮流交给变量 f，对每个执行一遍中间那段。' },
      { q: '下面哪个描述最能一次让系统写出对的脚本？', opts: ['帮我写个脚本整理下载文件夹', '写一个 Bash 脚本整理 ~/Downloads：按扩展名分类，子文件夹不存在就创建，同名文件跳过并提示，不要删除任何文件，最后打印移动了多少个', '写个好用的脚本', '帮我自动化一下'], a: 1, why: '说清输入、规则（含例外）、输出和「不许做什么」，一次就成，而且你回头能判断它对不对。' },
      { q: '关于脚本的安全，哪句是对的？', opts: ['系统生成的脚本可以直接放心跑', '跑之前先读一遍找 rm / mv / >，再干跑、再在假数据上试', '只要不是 rm 就都安全', '脚本不可能造成损失'], a: 1, why: '会自动删东西、覆盖文件、往外发数据的脚本，写错一次代价可能很大。' }
    ]}
  ]},

  'm1-8': { segs: [
    { t: 'text', h: '双击安装包之后发生了什么', b:
      '<p>你下载安装包、双击、点「下一步」、进度条走几秒、开始菜单多一个图标。中间电脑做了三件事：</p>' +
      '<ul>' +
      '<li><strong>解压</strong>：安装包其实就是个压缩包，把里面的文件解压到你指定的文件夹。</li>' +
      '<li><strong>登记</strong>：告诉系统「我装在这儿了」，这样你点图标时系统才知道去哪找。</li>' +
      '<li><strong>做配置</strong>：建快捷方式、写几条设置、注册文件类型。</li>' +
      '</ul>' +
      '<p>装软件说到底就是这三件事。理解了这一点，你就能解释很多奇怪的现象。</p>' },
    { t: 'quiz', q: '装完了，开始菜单和桌面都找不到它。最该先做什么？',
      opts: ['重装一遍系统', '去 C:\\Program Files 下面找同名文件夹，里面通常有 .exe', '换个软件', '重启电脑十次'], a: 1,
      why: '多半是安装程序没登记，或者是「绿色版」免安装软件。找到那个 .exe 双击就能开。' },
    { t: 'text', h: '残留和包管理器', b:
      '<p>卸载了但硬盘空间没怎么变多，或者重装后发现上次的设置还在 —— 因为卸载程序只删它记得的东西：主程序文件。删不掉的有你用它生成的文档、写在系统里的设置（Windows 上叫注册表）、缓存、以及你放在别处的插件。这些加起来可能比软件本身还大。</p>' +
      '<p>程序员用另一种装法：<strong>包管理器</strong>。终端里敲一句 <code>brew install git</code>，它自己去网上找、下载、装好、登记。好处是快（装十个就是十行命令）、干净（自动装齐依赖）、能一键卸载、还能写进文档让新人和老同事环境一模一样。</p>' +
      '<p>代价是：默认装在固定位置不能随便选，而且它主要管命令行工具和开发库，微信、PS 这类桌面软件还是得手动装。</p>' },
    { t: 'quiz', q: '包管理器相比手动装，最大的好处不包括下面哪一项？',
      opts: ['自动把缺的依赖一起装上', '能一键卸载干净', '能装所有桌面软件，包括微信和 PS', '装法可以写进文档，团队环境一致'], a: 2,
      why: '包管理器主要管命令行工具和开发库，桌面软件大部分还是得手动装。' },
    { t: 'text', h: '「装上了」和「能用了」是两件事', b:
      '<p>一个学生照教程装 Python，装好之后敲 <code>python --version</code> 说找不到命令。他以为没装成功，又装了一遍，还是找不到。后来才发现：安装时有个复选框写着「Add Python to PATH」，默认<strong>没勾</strong>，他一路点下一步跳过了。</p>' +
      '<p>那个复选框干的事，就是把 Python 装在哪登记进系统。没勾，系统就不知道有这个程序。<strong>装开发工具时，凡是提到「PATH」「环境变量」「Add to」的选项，一律勾上</strong> —— 勾错了顶多多一条记录，不勾可能就要重装。</p>' +
      '<p>还有两个要记住的：<strong>装上了 ≠ 能用了</strong>（配置对、依赖齐才算能用）；<strong>版本会打架</strong>（A 项目要 1.0 版，B 项目要 2.0 版，有专门的虚拟环境和容器来解决，那是后面的事）。</p>' },
    { t: 'final', qs: [
      { q: '装完工具敲命令提示「不是内部或外部命令」，第一反应应该是什么？', opts: ['重装系统', '多半是 PATH 没配好，检查安装时有没有勾 Add to PATH', '软件是盗版的', '电脑中毒了'], a: 1, why: '系统沿着 PATH 找程序，找不到就报这个错。重新运行安装包选 Modify 补勾，或手动把目录加进 PATH。' },
      { q: '卸载软件后想清干净，该看哪几个地方？', opts: ['只看回收站', 'C:\\Program Files 和 C:\\Users\\你的名字\\AppData', '只看桌面', '只要卸载了就一定干净'], a: 1, why: '再带上 C:\\ProgramData。看到了确认没用再删。' },
      { q: '下面哪句话是对的？', opts: ['装上了就等于能用了', '装上了是把文件放好了，能用了还要配置对、依赖齐', '包管理器能保证装上的东西一定能用', '版本冲突不存在'], a: 1, why: '新手经常卡在「装上了」和「能用了」这两步之间。' }
    ]}
  ]},

  'm1-9': { segs: [
    { t: 'text', h: 'Git 到底在干什么', b:
      '<p>你有一个文件夹，里面是你正在写的东西。每次改完一些内容，你告诉 Git「记一下」，它就把文件夹里所有文件当时的样子存一份。</p>' +
      '<p>存下来的每一份叫一个<strong>提交</strong>，每个提交带着三样东西：<strong>文件内容、谁存的、你写的一句说明</strong>。所有提交按时间排成一条线，就是你的<strong>项目历史</strong>。想回到哪个时刻，就回到哪个时刻。</p>' +
      '<p>全部历史都存在文件夹里一个叫 <code>.git</code> 的隐藏目录里。核心就五条命令：<code>init</code> 建仓库、<code>add</code> 挑出要提交的、<code>commit</code> 存下来、<code>log</code> 看历史、<code>checkout</code> 回到某个时刻。</p>' },
    { t: 'quiz', q: '一次提交里包含什么？',
      opts: ['只有文件当前的内容', '文件内容 + 谁存的 + 一句说明', '只有一句说明', '只有修改时间的记录'], a: 1,
      why: '三样缺一不可。那句说明很重要 —— 三个月后你全靠它回忆这次改了什么。' },
    { t: 'text', h: '分支是什么', b:
      '<p>你写了一份文档，想试试完全不同的写法，但不想把现在这版改乱。一个办法是先复制一份、改复制的那份，改得好就替换回来。</p>' +
      '<p>分支做的就是这件事，<strong>但它不复制文件</strong>。它只是记下「从这里分出去一条新的线」。你在这条线上改东西、提交，主线上的文件一个都没动。等你做完了觉得可以，就把它合回主线；觉得不行，删掉这条线，主线还是原样。</p>' +
      '<p>为什么不用复制文件的办法？因为复制出来两份会慢慢变得不一样，你也记不清哪个是最新的。<strong>分支和主线共享同一份历史，只是往前走的路不一样</strong>，合起来的时候 Git 知道两边各改了什么。</p>' },
    { t: 'quiz', q: '分支和「复制一份文件」的本质区别是？',
      opts: ['分支更快', '分支和主线共享同一份历史，复制出来的是两份会各自漂移的文件', '分支占更多空间', '没区别，就是换个说法'], a: 1,
      why: '因为共享历史，合并时 Git 才知道两边各改了什么。这是分支真正的价值：试错不要成本。' },
    { t: 'text', h: '它不适合干什么，和三个要小心的命令', b:
      '<p><strong>不适合</strong>：大文件（每次提交存一份完整快照，几个几百兆的视频进去仓库就涨到几个 G）、图片视频这类文件（能存，但算不出「改了哪里」，每次都是一整份新的）。<strong>它不是备份工具</strong> —— 它管的是项目的版本，不管你的文档、照片、桌面。</p>' +
      '<p>让系统帮你处理 Git 问题时要小心，「撤销」有好几种，含义完全不同：</p>' +
      '<ul>' +
      '<li><code>git reset --hard</code> —— <strong>会把未提交的改动彻底抹掉，找不回来</strong></li>' +
      '<li><code>git revert</code> —— 做一个反向的修改，历史还在，只是多一条抵消记录，<strong>这个安全</strong></li>' +
      '<li><code>git checkout -- 文件</code> —— 把文件恢复成上次提交的样子，之后改的全没了</li>' +
      '</ul>' +
      '<p>拿不准就先 <code>git stash</code>，它把改动暂时收起来，随时能拿回来。</p>' },
    { t: 'final', qs: [
      { q: '下面哪个 Git 操作是安全的撤销方式？', opts: ['git reset --hard', 'git revert', 'git checkout -- 文件', '直接删掉 .git 目录'], a: 1, why: 'revert 是加一条反向记录，历史完整保留。reset --hard 会丢东西。' },
      { q: '为什么 Git 不适合用来存视频素材？', opts: ['因为它不支持中文路径', '因为每次提交存完整快照，大文件会让仓库迅速膨胀', '因为它只能存文本', '因为视频会被压缩'], a: 1, why: '几个几百兆的视频进去，仓库会涨到几个 G，复制一次要等很久。' },
      { q: '想让系统帮你处理 Git 问题，先把什么贴给它？', opts: ['只说「我想撤销一下」', 'git status 和 git log 的输出', '整个项目的压缩包', '错误截图但不说做了什么'], a: 1, why: '让它看清你现在的状态再问怎么办。别只说「我想撤销一下」—— 不同含义的撤销后果差别极大。' }
    ]}
  ]}

});

